#include <iostream>
#include <algorithm>
#include <array>
#include <iterator>

bool greater9(int x) {
    return x > 9;
}

int main() {
    const std::size_t SIZE = 10;
    const std::array<int, SIZE> init = {10, 2, 10, 4, 16, 6, 14, 8, 12, 10};
    std::ostream_iterator<int> output(std::cout, " ");

    // 1. remove in-place
    std::array<int, SIZE> a1(init);
    std::cout << "a1 before removing all 10s:\n   ";
    std::copy(a1.cbegin(), a1.cend(), output);
    auto newLast1 = std::remove_if(a1.begin(), a1.end(), [](int value){return value == 10;});
    std::cout << "\na1 after removing all 10s:\n   ";
    std::copy(a1.begin(), newLast1, output);

    // 2. remove_copy
    std::array<int, SIZE> a2(init);
    std::array<int, SIZE> c = {0};
    std::cout << "\n\na2 before removing all 10s and copying:\n   ";
    std::copy(a2.cbegin(), a2.cend(), output);
    std::remove_copy(a2.cbegin(), a2.cend(), c.begin(), 10);
    std::cout << "\nc after removing all 10s from a2:\n   ";
    std::copy(c.cbegin(), c.cend(), output);

    // 3. remove_if in-place
    std::array<int, SIZE> a3(init);
    std::cout << "\n\na3 before removing all elements greater than 9:\n   ";
    std::copy(a3.cbegin(), a3.cend(), output);
    auto newLast3 = std::remove_if(a3.begin(), a3.end(), greater9);
    std::cout << "\na3 after removing all elements greater than 9:\n   ";
    std::copy(a3.begin(), newLast3, output);

    // 4. remove_copy_if
    std::array<int, SIZE> a4(init);
    std::array<int, SIZE> c2 = {0};
    std::cout << "\n\na4 before removing all elements\ngreater than 9 and copying:\n   ";
    std::copy(a4.cbegin(), a4.cend(), output);
    std::remove_copy_if(a4.cbegin(), a4.cend(), c2.begin(), greater9);
    std::cout << "\nc2 after removing all elements\ngreater than 9 from a4:\n   ";
    std::copy(c2.cbegin(), c2.cend(), output);
    std::cout << std::endl;

    return 0;
}

#include <iostream>
#include <algorithm>
#include <array>

bool greater9(int x) {
    return x > 9;
}

int main() {
    const std::size_t SIZE = 10;
    const std::array<int, SIZE> init = {10, 2, 10, 4, 16, 6, 14, 8, 12, 10};

    // 1. replace in-place
    std::array<int, SIZE> a1(init);
    std::cout << "a1 before replacing all 10s:\n   ";
    for (int x : a1) { std::cout << x << ' '; }
    std::replace(a1.begin(), a1.end(), 10, 100);
    std::cout << "\na1 after replacing 10s with 100s:\n   ";
    for (int x : a1) { std::cout << x << ' '; }

    // 2. replace_copy
    std::array<int, SIZE> a2(init);
    std::array<int, SIZE> c1{};
    std::cout << "\n\na2 before replacing all 10s and copying:\n   ";
    for (int x : a2) { std::cout << x << ' '; }
    std::replace_copy(a2.cbegin(), a2.cend(), c1.begin(), 10, 100);
    std::cout << "\nc1 after replacing all 10s in a2:\n   ";
    for (int x : c1) { std::cout << x << ' '; }

    // 3. replace_if in-place
    std::array<int, SIZE> a3(init);
    std::cout << "\n\na3 before replacing values greater than 9:\n   ";
    for (int x : a3) { std::cout << x << ' '; }
    std::replace_if(a3.begin(), a3.end(), greater9, 100);
    std::cout << "\na3 after replacing all values greater\nthan 9 with 100s:\n   ";
    for (int x : a3) { std::cout << x << ' '; }

    // 4. replace_copy_if
    std::array<int, SIZE> a4(init);
    std::array<int, SIZE> c2{};
    std::cout << "\n\na4 before replacing all values greater than 9 and copying:\n   ";
    for (int x : a4) { std::cout << x << ' '; }
    std::replace_copy_if(a4.cbegin(), a4.cend(), c2.begin(), greater9, 100);
    std::cout << "\nc2 after replacing all values greater than 9 in a4:\n   ";
    for (int x : c2) { std::cout << x << ' '; }
    std::cout << std::endl;

    return 0;
}
